def execute(sock,entry,mode):
    if mode=='Simple':return wire.simple_query(sock,entry['sql'])
    sql='SELECT $1::interval / $2::double precision AS result' if 'inputs' in entry else entry['sql']
    oids=[1186,701] if 'inputs' in entry else []
    parse=b'\0'+sql.encode()+b'\0'+struct.pack('!H',len(oids))+b''.join(struct.pack('!I',oid) for oid in oids)
    bind=b'\0\0'+struct.pack('!HH',0,len(entry.get('inputs',[])))
    for value in entry.get('inputs',[]):
        raw=None if value is None else value.encode();bind+=struct.pack('!i',-1 if raw is None else len(raw))+(raw or b'')
    bind+=struct.pack('!H',0)
    sock.sendall(wire.typed(b'P',parse)+wire.typed(b'D',b'S\0')+wire.typed(b'B',bind)+wire.typed(b'D',b'P\0')+wire.typed(b'E',b'\0'+struct.pack('!I',0))+wire.typed(b'S'))
    return wire.read_until_ready(sock)

def signature(messages,runner):
    rows,state,message,headers,tag,oids=runner.decode_wire_result(messages,include_types=True)
    return dict(rows=rows,states=[wire.diagnostic_fields(body).get(b'C',b'').decode() for kind,body in messages if kind==b'E'],
        descriptions=[body.hex() for kind,body in messages if kind==b'T'],parameters=[body.hex() for kind,body in messages if kind==b't'],
        data=[body.hex() for kind,body in messages if kind==b'D'],commands=[body.hex() for kind,body in messages if kind==b'C'],
        frames=[kind.decode() for kind,body in messages],ready=[body.decode() for kind,body in messages if kind==b'Z'])

