def main():
    review=Review(LABEL)
    output=Path(os.environ.get("INTERVAL_DIVISION_OUTPUT_DIR") or tempfile.mkdtemp(prefix="dbms-interval-div-"))
    output.mkdir(parents=True,exist_ok=True)
    assert len(PLAN)==EXPECTED_CONTROLS and sum(e['mode']=='Extended' for e in PLAN)==53
    assert sum('inputs' in e and e['mode']=='Extended' for e in PLAN)==4
    observations=[];complete=False
    def save():
        (output/'observations.json').write_text(json.dumps(dict(complete=complete,controls=observations,
            failures=len(review.failures),source_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()),indent=2)+'\n')
    try:
        for entry in PLAN:
            messages=execute(review.sock,entry,entry['mode']);actual=signature(messages,review.runner)
            valid=actual==entry['expected']
            observations.append(dict(entry,actual=actual,passed=valid,raw=[[kind.decode(),body.hex()] for kind,body in messages]))
            review.record((entry['label'],entry['mode'],entry['sql']),valid,actual,entry['expected'])
            if len(observations)%20==0:save()
        complete=True
        review.complete(EXPECTED_CONTROLS)
    finally:
        save()
        print(LABEL+"_OBSERVATIONS",str(output/'observations.json'),flush=True)
        review.close()

if __name__=='__main__':main()
